-- State transitions declared for GamificationGoal: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION engagement.gamification_goals_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('draft', 'canceled'), ('draft', 'inprogress'), ('inprogress', 'canceled'), ('inprogress', 'failed'), ('inprogress', 'reached'), ('reached', 'canceled'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: gamification_goals.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_gamification_goals__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS gamification_goals_state_transition_check ON engagement.gamification_goals;
CREATE TRIGGER gamification_goals_state_transition_check
    BEFORE UPDATE OF "state" ON engagement.gamification_goals
    FOR EACH ROW EXECUTE FUNCTION engagement.gamification_goals_state_transition_check();
